 const sandbox={document:{getElementById:id=>{assert(nodes.has(id),'Missing node '+id);return nodes.get(id)}},DegreeTemplateWorkspace:W,DegreeAccount:{async session(){if(onSession)await onSession();return{user:server.signedIn?{id:'sb-student'}:null}}},URL,URLSearchParams,Map,Set,Date,JSON,console,location:{search},sessionStorage:{getItem:key=>storage.get(key)||null,setItem:(key,value)=>storage.set(key,String(value)),removeItem:key=>storage.delete(key)},setTimeout:(callback,delay)=>{timers.set(++timerNumber,{callback,delay});return timerNumber},clearTimeout:id=>timers.delete(id),addEventListener:(name,callback)=>{events[name]=callback}};
